-- ============================================
-- LUMA — Thème 7 : MOYEN 1/3 x4 — Faire du shopping avec un budget serré
-- ============================================


update scenarios set content = '{"characters": {"clerk": "le vendeur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(You have $60 to spend on a work outfit — need to be strategic.)", "text_fr": "(Vous avez 60$ à dépenser pour une tenue de travail — il faut être stratégique.)", "choices": [{"text": "(Start by browsing the sale rack first.)", "text_fr": "(Commence par parcourir le rayon soldes d''abord.)", "next": "n2"}, {"text": "(Look for a basic blazer first, then build around it.)", "text_fr": "(Cherche d''abord un blazer basique, puis construis autour.)", "next": "n2b"}]}, "n2": {"speaker": "clerk", "text": "Looking for anything specific? Our sale section has some great deals today.", "text_fr": "Vous cherchez quelque chose de spécifique ? Notre rayon soldes a de bonnes affaires aujourd''hui.", "choices": [{"text": "I''m looking for a work outfit, on a pretty tight budget.", "text_fr": "Je cherche une tenue de travail, avec un budget assez serré.", "next": "n3"}]}, "n2b": {"speaker": "clerk", "text": "We have some nice blazers starting at $25, want to see them?", "text_fr": "On a de beaux blazers à partir de 25$, vous voulez les voir ?", "choices": [{"text": "Yes, please, that sounds like a good starting point.", "text_fr": "Oui, s''il vous plaît, ça a l''air d''un bon point de départ.", "next": "n3"}]}, "n3": {"speaker": "clerk", "text": "Let me show you a few options that would work well together.", "text_fr": "Laissez-moi vous montrer quelques options qui iraient bien ensemble.", "choices": [{"text": "Perfect, I''m open to suggestions.", "text_fr": "Parfait, je suis ouvert aux suggestions.", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(You find a blazer for $22 and a blouse for $18 — good start.)", "text_fr": "(Vous trouvez un blazer à 22$ et un chemisier à 18$ — bon début.)", "choices": [{"text": "These two work great together, what about pants?", "text_fr": "Ces deux-là vont bien ensemble, et pour le pantalon ?", "next": "n5"}, {"text": "I love these, but I''m worried about going over budget with pants too.", "text_fr": "J''adore ça, mais j''ai peur de dépasser le budget avec le pantalon aussi.", "next": "n5b"}]}, "n5": {"speaker": "clerk", "text": "We have simple black trousers for $15, that would complete the look nicely.", "text_fr": "On a des pantalons noirs simples à 15$, ça compléterait bien le look.", "choices": [{"text": "That works with my budget, let''s add those.", "text_fr": "Ça marche avec mon budget, ajoutons ça.", "next": "n6"}]}, "n5b": {"speaker": "clerk", "text": "Let''s see — with the blazer and blouse, you''re at $40, leaving $20 for pants.", "text_fr": "Voyons — avec le blazer et le chemisier, vous êtes à 40$, ce qui laisse 20$ pour le pantalon.", "choices": [{"text": "Oh good, that gives me some room. Any options around $15-20?", "text_fr": "Oh super, ça me laisse de la marge. Des options autour de 15-20$ ?", "next": "n6"}]}, "n6": {"speaker": "you_thought", "text": "(You try on the full outfit — it looks professional and put together.)", "text_fr": "(Vous essayez la tenue complète — ça a l''air professionnel et bien assorti.)", "choices": [{"text": "This looks great! I''m really happy with how it turned out.", "text_fr": "Ça a l''air super ! Je suis vraiment content du résultat.", "next": "n7"}, {"text": "I love it, but let me double check the total before deciding.", "text_fr": "J''adore, mais laissez-moi revérifier le total avant de décider.", "next": "n7b"}]}, "n7": {"speaker": "clerk", "text": "You look fantastic! Total comes to $55, well within your budget.", "text_fr": "Vous avez l''air fantastique ! Le total est de 55$, bien dans votre budget.", "choices": [{"text": "That''s perfect, I''ll take the whole outfit.", "text_fr": "C''est parfait, je prends toute la tenue.", "next": "n8"}]}, "n7b": {"speaker": "clerk", "text": "Of course, let me add it up — blazer, blouse, and pants comes to $55 total.", "text_fr": "Bien sûr, laissez-moi additionner — blazer, chemisier et pantalon, ça fait 55$ au total.", "choices": [{"text": "That''s within budget, I''ll take it all.", "text_fr": "C''est dans le budget, je prends tout.", "next": "n8"}]}, "n8": {"speaker": "clerk", "text": "Great choice! You managed to build a full outfit while staying on budget.", "text_fr": "Excellent choix ! Vous avez réussi à construire une tenue complète en restant dans le budget.", "choices": [{"text": "Thank you for helping me find such good options.", "text_fr": "Merci de m''avoir aidé à trouver de si bonnes options.", "next": "end_budget"}]}, "end_budget": {"speaker": "clerk", "text": "My pleasure! You''ll look great at work in this.", "text_fr": "Avec plaisir ! Vous aurez fière allure au travail avec ça.", "end": true, "ending_label": "Tenue complète trouvée dans le budget 👔💰✅"}}}'::jsonb, is_playable = true
where title = 'Faire du shopping avec un budget serré'
  and theme_id = (select id from scenario_themes where position = 7 and language_id = (select id from languages where code = 'en'));
